const payload = items[0].json ?? {};
const contextInput = payload.context ?? {};

const recentSearches = payload.recentSearches ?? contextInput.recentSearches ?? [];
const recentClicks = payload.recentClicks ?? contextInput.recentClicks ?? [];
const cartData = payload.cart ?? contextInput.cart ?? {};
const featuredProducts = payload.featuredProducts ?? contextInput.featuredProducts ?? [];
const orders = payload.orders ?? contextInput.orders ?? [];
const cartItems = Array.isArray(cartData.items) ? cartData.items : Array.isArray(cartData) ? cartData : [];

const formatList = (list, mapper) =>
  Array.isArray(list) && list.length > 0
    ? list.map(mapper).join('\n')
    : 'Không có dữ liệu.';

const lines = [
  `Khách hàng: ${payload.customer?.name ?? 'Ẩn danh'} (${payload.customer?.email ?? 'N/A'})`,
  `Ngôn ngữ: ${payload.locale ?? 'vi-VN'}`,
  '\nLịch sử tìm kiếm:',
  formatList(recentSearches.slice(-5), (s, index) => `${index + 1}. ${s}`),
  '\nSản phẩm đã xem gần đây:',
  formatList(recentClicks.slice(-5), (item, index) => `${index + 1}. ${item.name} - ${item.price ?? 'N/A'} (${item.theme ?? 'không rõ'})`),
  '\nSản phẩm trong giỏ hàng:',
  formatList(cartItems, (item, index) => `${index + 1}. ${item.name ?? item.title ?? 'Không rõ'} ×${item.quantity ?? 1} - ${item.price ?? 'N/A'}`)
];

const basePrompt = payload.prompt ?? `Bạn là trợ lý bán hàng LEGO. Dựa trên dữ liệu:
${lines.join('\n')}

Hãy đề xuất tối đa 3 sản phẩm LEGO phù hợp nhất. Mỗi đề xuất nên có:
- Tên sản phẩm
- Mức giá
- Lý do ngắn gọn (≤ 20 từ)
- Tag thể hiện chủ đề/độ tuổi nếu có.

Định dạng phản hồi JSON với cấu trúc { "recommendations": [ { "name": "", "price": "", "reason": "", "tags": [] } ] }.`;

const messages = Array.isArray(payload.messages) && payload.messages.length
  ? payload.messages
  : [
      ...(payload.systemPrompt ? [{ role: 'system', content: payload.systemPrompt }] : []),
      { role: 'user', content: basePrompt }
    ];

const generationConfigInput = payload.generationConfig ?? {};
const generationConfig = Object.fromEntries(
  Object.entries({
    temperature: payload.temperature ?? generationConfigInput.temperature ?? 0.6,
    topP: payload.topP ?? generationConfigInput.topP,
    topK: payload.topK ?? generationConfigInput.topK,
    maxOutputTokens: payload.maxOutputTokens ?? generationConfigInput.maxOutputTokens ?? 256
  }).filter(([, value]) => value !== undefined)
);

const context = {
  recentSearches,
  recentClicks,
  cart: Array.isArray(cartItems) ? { items: cartItems } : cartData,
  featuredProducts,
  orders
};

return [{ json: {
  messages,
  context,
  customer: payload.customer ?? {},
  generationConfig,
  sessionId: payload.sessionId ?? null
} }];

const response = items[0].json ?? {};
return [{ json: {
  answer: response.reply,
  metadata: response.metadata,
  session: response.session,
  raw: response
} }];
